-- IDs on the portal's New list that have no live claim yet.
select t.app_id as application_id, 'sweep' as source
from jsonb_array_elements_text($1::jsonb) as t(app_id)
where not exists (
  select 1 from runs r where r.application_id = t.app_id and r.status in ('processing', 'completed')
)
order by t.app_id;

